// Regenerates site/src/engine/common-words-data.js: node scripts/gen-common-words.js
// Source data is the wordfreq large_en corpus (https://github.com/rspeer/wordfreq),
// Apache-2.0 — the same frequency data the space-out tool fetches at runtime.
// Attribution rides in the generated file's header and THIRD-PARTY-NOTICES.
import { writeFile } from 'node:fs/promises';
import { gunzipSync } from 'node:zlib';
import { UNIGRAM_CORPUS_URL, msgpackDecode, buildCorpusFromMsgpack } from '../site/src/engine/segmenter.js';

const OUT = new URL('../site/src/engine/common-words-data.js', import.meta.url);
const N = 30000;   // top-N by frequency — see docs/design.md § family key

const res = await fetch(UNIGRAM_CORPUS_URL);
if (!res.ok) throw new Error(`fetch ${UNIGRAM_CORPUS_URL}: ${res.status}`);
const { map } = buildCorpusFromMsgpack(msgpackDecode(gunzipSync(Buffer.from(await res.arrayBuffer()))));

const words = [...map.entries()]
  .filter(([w]) => /^[a-z]{2,15}$/.test(w))   // clean single alpha tokens: family stems only
  .sort((a, b) => b[1] - a[1])                // descending frequency
  .slice(0, N)
  .map(([w]) => w)
  .sort();                                    // alphabetical: stable diffs + tighter gzip

const header = `'use strict';

// Generated by scripts/gen-common-words.js — do not edit by hand. The ${N} most
// frequent English words, used by morphology.js as a family-key tiebreak: among a
// word's candidate stems, a common one wins over a spurious longer stem (the French
// \`calle\` for \`called\`) that would otherwise take the length tiebreak and split the
// paradigm off its base. Stems no common word covers fall back to longest, so
// out-of-dictionary crossword fill still anchors against the list's own vocabulary.
//
// Source: wordfreq large_en corpus (https://github.com/rspeer/wordfreq), Apache-2.0
//   — the same frequency data the space-out tool fetches at runtime. The notice
//   rides here and in THIRD-PARTY-NOTICES.

export const COMMON_WORDS = \`
${words.join('\n')}
\`;
`;
await writeFile(OUT, header);
console.log(`Wrote ${OUT.pathname}: ${words.length} words`);
